package rules

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/fs"
	"main/types"
	"path/filepath"
	"reflect"
	"sort"
	"strconv"
	"strings"
)

// TypeScriptHeader explains where the generated rule IDs come from.
const TypeScriptHeader = `/**
 * This file is auto-generated by the rules-ids command of the Go validator.
 * Do not edit this file manually. Run ` + "`npm run repo:validator-rules`" + ` to regenerate.
 *
 * Source: validation implementations in modules/operation/apps/validator/validator/src.
 * Includes validation rule IDs and runtime notice IDs discovered from the source.
 */
`

// TypeScript discovers rule IDs from validation source instead of configuration fields.
func TypeScript() (map[string][]byte, error) {
	return RenderTypeScript("validations")
}

func RenderTypeScript(sourceDir string) (map[string][]byte, error) {
	found := map[string]bool{"file_validation": true, "file_not_found_in_rules": true}
	root := reflect.TypeOf(types.GtfsRules{})
	for i := range root.NumField() {
		name := root.Field(i).Tag.Get("json")
		if name != "file_validation" {
			found[name+"_file_missing"] = true
		}
	}
	err := filepath.WalkDir(sourceDir, func(path string, entry fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if entry.IsDir() || !strings.HasSuffix(path, ".go") || strings.HasSuffix(path, "_test.go") {
			return nil
		}
		file, err := parser.ParseFile(token.NewFileSet(), path, nil, 0)
		if err != nil {
			return err
		}
		var literal func(ast.Expr) string
		literal = func(expr ast.Expr) string {
			if ident, ok := expr.(*ast.Ident); ok && ident.Obj != nil {
				if spec, ok := ident.Obj.Decl.(*ast.ValueSpec); ok {
					for i, name := range spec.Names {
						if name.Name == ident.Name && i < len(spec.Values) {
							return literal(spec.Values[i])
						}
					}
				}
			}
			if value, ok := expr.(*ast.BasicLit); ok && value.Kind == token.STRING {
				text, _ := strconv.Unquote(value.Value)
				return text
			}
			return ""
		}
		ast.Inspect(file, func(node ast.Node) bool {
			switch node := node.(type) {
			case *ast.CallExpr:
				if selector, ok := node.Fun.(*ast.SelectorExpr); ok {
					index := -1
					if selector.Sel.Name == "Rule" {
						index = 0
					}
					if selector.Sel.Name == "NewValidationContext" {
						index = 2
					}
					if index >= 0 && len(node.Args) > index {
						if id := literal(node.Args[index]); id != "" {
							found[id] = true
						}
					}
				}
			case *ast.CompositeLit:
				if selector, ok := node.Type.(*ast.SelectorExpr); ok && selector.Sel.Name == "RuleActions" {
					for _, element := range node.Elts {
						if pair, ok := element.(*ast.KeyValueExpr); ok {
							if id := literal(pair.Key); id != "" {
								found[id] = true
							}
						}
					}
				}
			}
			return true
		})
		return nil
	})
	if err != nil {
		return nil, err
	}
	ids := make([]string, 0, len(found))
	for id := range found {
		ids = append(ids, id)
	}

	sort.Strings(ids)
	for i := 1; i < len(ids); i++ {
		if ids[i] == ids[i-1] {
			return nil, fmt.Errorf("duplicate rule id %s", ids[i])
		}
	}

	var output bytes.Buffer
	output.WriteString("/* * */\n\nimport { z } from 'zod';\n\n/* * */\n\n")
	output.WriteString(TypeScriptHeader)
	output.WriteString("\nexport const GtfsValidatorRuleIdValues = [\n")
	for _, id := range ids {
		fmt.Fprintf(&output, "\t%s,\n", quote(id))
	}
	output.WriteString(`] as const;

export const GtfsValidatorRuleIdSchema = z
	.string()
	.transform(value => String(value).toLowerCase())
	.pipe(z.enum(GtfsValidatorRuleIdValues));

export type GtfsValidatorRuleId = z.infer<typeof GtfsValidatorRuleIdSchema>;
`)
	return map[string][]byte{"rule-ids.ts": output.Bytes()}, nil
}

func jsonName(field reflect.StructField) (string, error) {
	tag, ok := field.Tag.Lookup("json")
	if !ok {
		return "", fmt.Errorf("field %s has no json tag", field.Name)
	}
	name, _, _ := strings.Cut(tag, ",")
	if name == "" || name == "-" {
		return "", fmt.Errorf("field %s has unsupported json tag %q", field.Name, tag)
	}
	return name, nil
}

var tsStringEscaper = strings.NewReplacer(`\`, `\\`, "'", `\'`, "\n", `\n`, "\r", `\r`)

// quote renders a single-quoted TypeScript string literal.
func quote(value string) string {
	return "'" + tsStringEscaper.Replace(value) + "'"
}
